findings.codeql_raw_query:
/**
 * @name CLI command injection via markdown-it-py
 * @description Detects use of subprocess or os.system in the markdown_it.cli.parse module that could be influenced by untrusted markdown or arguments.
 * @kind path-problem
 * @problem.severity error
 * @id py/markdown-it-cli-command-injection
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

/**
 * Data-flow configuration: from remote/CLI input to system command execution
 */
module CmdInjConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      // Calls to os.system, subprocess.run, subprocess.Popen, etc.
      call =
        API::moduleImport("os").getMember("system").getACall()
        or
        call = API::moduleImport("subprocess").getMember(["run", "Popen", "call", "check_call", "check_output"]).getACall()
      |
      // Command argument is typically the first positional argument
      sink = call.getArg(0)
    )
  }
}

module CmdInjFlow = TaintTracking::Global<CmdInjConfig>;
import CmdInjFlow::PathGraph

from CmdInjFlow::PathNode source, CmdInjFlow::PathNode sink
where CmdInjFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches a system command in markdown-it-py CLI.", source, "user input"
